225	    /**
226	     * Whether an existing owner already shares the same last name and address as the
227	     * given owner. Both fields are compared case-insensitively with runs of whitespace
228	     * collapsed to a single space (and surrounding whitespace trimmed).
229	     *
230	     * @param owner the candidate owner being created
231	     * @return {@code true} if a matching owner already exists
232	     */
233	    private boolean isHouseholdDuplicate(Owner owner) {
234	        String lastName = normalize(owner.getLastName());
235	        String address = normalize(owner.getAddress());
236	        return this.clinicService.findAllOwners().stream()
237	            .anyMatch(existing -> normalize(existing.getLastName()).equals(lastName)
238	                && normalize(existing.getAddress()).equals(address));
239	    }
240	
241	    /**
242	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
243	     * trim, collapse internal runs of whitespace to a single space and lower-case.
244	     */
245	    private static String normalize(String value) {
246	        if (value == null) {
247	            return "";
248	        }
249	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
250	    }
251	
252	    /**
253	     * Build the next customer code, formatted {@code <LAST3>-<NNNN>}: LAST3 is the
254	     * upper-cased first three letters of the given last name and NNNN is a global
255	     * 4-digit zero-padded sequence equal to one more than the current number of
256	     * owners (e.g. {@code SMI-0007}).
257	     *
258	     * @param lastName the owner's last name
259	     * @return the assigned customer code
260	     */
261	    private String nextCustomerCode(String lastName) {
262	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
263	        long sequence = this.clinicService.findAllOwners().size() + 1L;
264	        return String.format("%s-%04d", last3, sequence);
265	    }
266	
267	    /**
268	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
269	     * code when present, otherwise assume country code '+61' and drop a single
270	     * leading '0' from the national digits. Spaces, dashes and brackets are
271	     * stripped. The result must contain 8 to 15 digits after the '+'.
272	     *
273	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
274	     *         input cannot form a valid E.164 number.
275	     */
276	    private static String toE164(String raw) {
277	        if (raw == null) {
278	            return null;
279	        }
280	        String cleaned = raw.replaceAll("[\\s()-]", "");
281	        String digits;
282	        if (cleaned.startsWith("+")) {
283	            digits = cleaned.substring(1);
284	        } else {
285	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
286	            digits = "61" + national;
287	        }
288	        if (!digits.matches("\\d{8,15}")) {
289	            return null;
290	        }
291	        return "+" + digits;
292	    }
293	}
